SELECT name, age
FROM students
WHERE age > 16;

SELECT name, city
FROM students
WHERE city IN ('Qarshi', 'Toshkent');

SELECT name, score
FROM students
WHERE score BETWEEN 80 AND 95;

SELECT city, COUNT(*) AS total_students
FROM students
GROUP BY city;

SELECT students.name, courses.title
FROM students
INNER JOIN courses ON students.course_id = courses.id;

SELECT students.name, courses.title
FROM students
LEFT JOIN courses ON students.course_id = courses.id;

SELECT name,
       CASE WHEN score >= 90 THEN 'Gold' ELSE 'Standard' END AS level
FROM students;
